// ============================================================
// Curadoria Aprovado → decide o que gerar no ComfyUI RunPod
// Recebe do MineraAI: item com video + enriquecimento (hooks, analise, roteiro)
// ============================================================
const body = $input.first().json.body || $input.first().json;
const item = body.item || body;
const videoOrig = item.video || item;
const enriquecimento = item.enriquecimento || {};
const roteiroCurado = item.roteiro || enriquecimento.roteiro || {};

// CONFIGURAÇÃO — edite conforme seu fluxo
const config = {
  salvar_biblioteca: true,
  // O que gerar no ComfyUI RunPod quando aprova
  gerar_conteudo: true,           // liga/desliga geração automática
  tipo_conteudo: 'misto',         // 'imagem' | 'video' | 'misto' (imagem+video)
  estilo: 'ugc',                  // ugc, dark, cinematic, produto, anime
  duracao_video: 6,               // segundos
  // Se false, só salva na biblioteca e não gera nada
  // Se true e tipo=misto, gera kit: capa + 3 cenas + video curto
  webhook_externo: '',            // ex: https://seu-scheduler.com/webhook para agendar post
  usar_fabrica_mineraai: true,    // true = chama /api/fabrica/jobs (que já dispara RunPod), false = chama RunPod direto
};

// Monta roteiro final a partir do enriquecimento
let roteiroFinal = {
  hook: enriquecimento.hooks?.[0]?.hook || enriquecimento.hooks?.[0] || roteiroCurado.hook || videoOrig.title || '',
  cenas: [],
  narracao: roteiroCurado.narracao || enriquecimento.titulo_sugerido || ''
};

if (roteiroCurado.cenas && roteiroCurado.cenas.length) {
  roteiroFinal.cenas = roteiroCurado.cenas;
} else if (enriquecimento.analise) {
  // Cria cenas baseadas na análise Viral Lab
  const formato = enriquecimento.analise.formato_detectado || 'UGC';
  roteiroFinal.cenas = [
    { nome: 'GANCHO', descricao: enriquecimento.hooks?.[0] || `Hook forte para ${videoOrig.title}`, prompt: `close-up reação, ${videoOrig.title}, estilo ${config.estilo}, 9:16 vertical, hook visual forte`, duracao: '2s' },
    { nome: 'PROBLEMA', descricao: `Dor que o produto resolve`, prompt: `pessoa com problema cotidiano, antes do produto, ${config.estilo}, 9:16`, duracao: '1s' },
    { nome: 'DEMO', descricao: `Demonstração real - formato ${formato}`, prompt: `${videoOrig.title}, demonstração uso real, prova social, ${config.estilo}, 9:16 vertical, alta qualidade`, duracao: '2s' },
    { nome: 'CTA', descricao: `CTA final`, prompt: `${videoOrig.title} com CTA visual 'LINK NA BIO', produto destaque, ${config.estilo}, 9:16`, duracao: '1s' }
  ];
} else {
  roteiroFinal.cenas = [
    { nome: 'GANCHO', prompt: `close-up ${videoOrig.title}, hook visual, ${config.estilo}, 9:16`, duracao: '2s' },
    { nome: 'DEMO', prompt: `${videoOrig.title} em uso, ${config.estilo}, 9:16 vertical`, duracao: '3s' },
    { nome: 'CTA', prompt: `${videoOrig.title} CTA LINK NA BIO, ${config.estilo}, 9:16`, duracao: '1s' }
  ];
}

// Prompts de imagem por cena
const promptsImagem = roteiroFinal.cenas.map(c => `${c.prompt || c.descricao}, ${videoOrig.title}, ${config.estilo}, vertical 9:16, alta qualidade`.slice(0,1200));
const promptVideo = `${config.estilo} video UGC ${videoOrig.title}, ${roteiroFinal.hook}, ${roteiroFinal.cenas.map(c => c.descricao).join('. ')}, vertical 9:16, movimento suave, ${config.duracao_video}s`.slice(0,1500);

// Prompt fábrica (para /api/fabrica/jobs)
let promptFabrica = '';
if (enriquecimento.hooks && enriquecimento.hooks.length) {
  const hookTxt = typeof enriquecimento.hooks[0] === 'string' ? enriquecimento.hooks[0] : enriquecimento.hooks[0].hook || '';
  promptFabrica = `Hook: ${hookTxt}. Produto: ${videoOrig.title}. Formato: ${enriquecimento.analise?.formato_detectado || 'UGC'}. Hashtags: ${(videoOrig.hashtags||[]).join(' ')}. Estilo ${config.estilo}. Roteiro: ${roteiroFinal.cenas.map(c => c.nome+': '+c.descricao).join(' | ')}`;
} else {
  promptFabrica = `${videoOrig.title}, estilo ${config.estilo}, vertical 9:16, alta qualidade. Roteiro: ${roteiroFinal.cenas.map(c => c.descricao).join('. ')}`;
}

return [{ json: { item_id: item.id || videoOrig.id, video: videoOrig, enriquecimento, roteiro: roteiroFinal, promptsImagem, promptVideo, promptFabrica, config, token: $env.N8N_TOKEN || body.token || '' } }];

// Monta workflow ComfyUI DIRETO no RunPod (sem passar pela Fábrica)
// Usa tipo_conteudo para escolher workflow: imagem, video ou misto
const data = $input.first().json;
const jobId = data.item_id;
const tipo = data.config.tipo_conteudo || 'misto';
const promptsImagem = data.promptsImagem || [];
const promptVideo = data.promptVideo || '';
const cenas = data.roteiro.cenas || [];
const seedBase = Math.floor(Math.random()*1e12);

let workflow = {};
workflow['1'] = { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: 'sd_xl_base_1.0.safetensors' } };
workflow['2'] = { class_type: 'EmptyLatentImage', inputs: { width: 768, height: 1344, batch_size: 1 } };
workflow['7'] = { class_type: 'CLIPTextEncode', inputs: { text: "low quality, blurry, watermark, logo, text, deformed", clip: ['1',1] } };

if (tipo === 'imagem' || tipo === 'misto') {
  promptsImagem.forEach((p, idx) => {
    const base = 10 + idx*10;
    workflow[`${base}`] = { class_type: 'CLIPTextEncode', inputs: { text: p, clip: ['1',1] } };
    workflow[`${base+1}`] = { class_type: 'KSampler', inputs: { seed: seedBase+idx, steps: 28, cfg: 7.5, sampler_name: 'dpmpp_2m', scheduler: 'karras', denoise: 1, model: ['1',0], positive: [`${base}`,0], negative: ['7',0], latent_image: ['2',0] } };
    workflow[`${base+2}`] = { class_type: 'VAEDecode', inputs: { samples: [`${base+1}`,0], vae: ['1',2] } };
    workflow[`${base+3}`] = { class_type: 'SaveImage', inputs: { filename_prefix: `mineraai/curadoria_${jobId}_${cenas[idx]?.nome || idx}`, images: [`${base+2}`,0] } };
  });
}

if (tipo === 'video' || tipo === 'misto') {
  workflow['40'] = { class_type: 'ADE_LoadAnimateDiffModel', inputs: { model_name: 'mm_sd_v15_v2.ckpt' } };
  workflow['41'] = { class_type: 'ADE_AnimateDiffLoaderWithContext', inputs: { model: ['1',0], motion_model: ['40',0] } };
  workflow['42'] = { class_type: 'EmptyLatentImage', inputs: { width: 512, height: 768, batch_size: 16 } };
  workflow['90'] = { class_type: 'CLIPTextEncode', inputs: { text: promptVideo, clip: ['1',1] } };
  workflow['91'] = { class_type: 'KSampler', inputs: { seed: seedBase+100, steps: 25, cfg: 7.0, sampler_name: 'dpmpp_2m', scheduler: 'karras', denoise: 1, model: ['41',0], positive: ['90',0], negative: ['7',0], latent_image: ['42',0] } };
  workflow['92'] = { class_type: 'VAEDecode', inputs: { samples: ['91',0], vae: ['1',2] } };
  workflow['93'] = { class_type: 'VHS_VideoCombine', inputs: { images: ['92',0], frame_rate: 8, loop_count: 0, filename_prefix: `mineraai/curadoria_${jobId}_video`, format: 'video/h264-mp4', pix_fmt: 'yuv420p', crf: 19 } };
}

return [{ json: { item_id: jobId, callback_url: `${$env.MINERAAI_URL}/api/curation/items/${jobId}/decision`, token: data.token, input: { workflow }, tipo, promptsImagem, video: data.video, enriquecimento: data.enriquecimento, roteiro: data.roteiro, webhook_externo: data.config.webhook_externo } }];

// Extrai resultado misto da curadoria direta
const r = $input.first().json;
const out = r.output || {};
let video_url = '';
let images = [];
const job = $('Montar ComfyUI Direto').first().json;

if (typeof out === 'object' && !Array.isArray(out)) {
  video_url = out.video_url || out.video || '';
  if (out.images) images = out.images.map((img, idx) => typeof img === 'string' ? { url: img, cena: job.promptsImagem[idx] || '' } : { url: img.url || '', cena: img.cena || '' });
  if (!video_url) {
    const s = JSON.stringify(out);
    const vM = s.match(/https?:\/\/[^"\s]+\.mp4[^"\s]*/);
    if (vM) video_url = vM[0];
  }
  if (!images.length) {
    const s = JSON.stringify(out);
    const iM = s.match(/https?:\/\/[^"\s]+\.(png|jpg|jpeg|webp)[^"\s]*/g);
    if (iM) images = iM.map((u, idx) => ({ url: u, prompt: job.promptsImagem[idx] || '' }));
  }
}

return [{ json: { item_id: job.item_id, video_url, images, tipo: job.tipo, video: job.video, enriquecimento: job.enriquecimento, roteiro: job.roteiro, webhook_externo: job.webhook_externo, token: job.token, cost_usd: r.cost || null } }];
